import{_ as o,c as e,o as t,a4 as d}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q14：this 指向的确定规则","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q14.md","filePath":"frontend/q14.md","lastUpdated":null}'),c={name:"frontend/q14.md"},n=d('<h1 id="q14-this-指向的确定规则" tabindex="-1">Q14：<code>this</code> 指向的确定规则 <a class="header-anchor" href="#q14-this-指向的确定规则" aria-label="Permalink to &quot;Q14：`this` 指向的确定规则&quot;">​</a></h1><p><code>this</code> 是函数内部的特殊关键字，指向调用它的上下文。其值不是在定义时确定，<strong>而是在函数调用时根据调用方式决定的</strong>，但有特殊情况：</p><ol><li><strong>全局下</strong>：严格模式下 <code>this</code> 为 <code>undefined</code>，非严格模式指向 <code>window</code>（浏览器）。</li><li><strong>作为对象方法调用</strong>：指向该对象（谁调用指向谁）。</li><li><strong>作为普通函数调用</strong>：严格模式 <code>undefined</code>，非严格 <code>window</code>。</li><li><strong>箭头函数</strong>：没有自己的 <code>this</code>，会捕获<strong>定义时</strong>外层作用域的 <code>this</code>，且一经绑定不可用 <code>call/apply/bind</code> 改变。</li><li><strong><code>call</code> / <code>apply</code> / <code>bind</code></strong>：显式绑定 <code>this</code>。<code>bind</code> 会返回一个新函数，永久绑定。</li><li><strong>作为构造函数（<code>new</code>）</strong>：<code>this</code> 指向新创建的实例对象。</li><li><strong>事件处理函数</strong>：指向绑定事件的 DOM 元素。</li></ol><p><strong>优先级</strong>：<code>new</code> 绑定 &gt; 显式绑定 &gt; 隐式绑定 &gt; 默认绑定（其中箭头函数是词法绑定，优先级不适用）。</p>',4),s=[n];function i(r,a,l,_,g,h){return t(),e("div",null,s)}const m=o(c,[["render",i]]);export{f as __pageData,m as default};
